--region public
---刷新ui
---@param equipDojo EquipDojo 装备数据(为空则隐藏)
function CardProgressionCardEquipBtnNode:RefreshUI(equipDojo)
    if equipDojo then
        ---@type EquipmentComponent
        local goodsVo = GoodsConfMgr:GetGoodsVoById(equipDojo.equipmentId)
        local cardConfMgr      = CardConfMgr:GetInstance()
        local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
        local rare = EquipUtils.GetQuality(equipDojo)
        CfUtils.SetActive(self.Content, true)
        CfUtils.SetActive(self.ImgIcon, false)
        CfUtils.SetActive(self.UIFX_CultivateOverseaEquipmentDialogBall, false)
        CfUtils.SetActive(self.Effect, false)
        CfUtils.FillImage(self.ImgEquipIcon, goodsVo.photoPath)
        CfUtils.SetUISwitchImage(self.Imgball1, rare + 1)
        CfUtils.SetUISwitchParticleSystem(self.ParticleGlow, rare)
        CfUtils.SetUISwitchParticleSystem(self.ParticleRing, rare)
        CfUtils.SetUISwitchParticleSystem(self.ParticleStar, rare)
        CfUtils.SetUISwitchImage(self.ImgGlow, rare)
        CfUtils.SetUISwitchImage(self.ImgRing, rare)
        local isEngraved = checkInt(equipDojo.bindPlayerCardId) > 0
        if not isEngraved then
            CfUtils.SetActive(self.CultivateOverseaEquipEngraveHead, false)
            
            if checkInt(equipDojo.level) == 0 then
                CfUtils.SetActive(self.Strengthen, false)
            else
                CfUtils.SetActive(self.Strengthen, true)
                CfUtils.SetUISwitchImage(self.TxtStrengthen, equipDojo.level)
            end
        else
            CfUtils.SetActive(self.CultivateOverseaEquipEngraveHead, true)
            local scr = CfUtils.GetLuaScr(self.CultivateOverseaEquipEngraveHead, CardProgressionConstants.EnvPath.EquipmentEngraveNode)
            if isNotNull(scr) then
                scr:RefreshNode(equipDojo)
            end

            CfUtils.SetActive(self.Strengthen, false)
        end
        
        CfUtils.FillImage(self.TypeImgIcon, EquipUtils.GetEquipmentSetIcon(equipDojo.equipmentId))
        -- for i = 1, CardProgressionConstants.EquipmentNum do
        --     local go = self.starNodes[i]
        --     if go == nil then
        --         go = self.StarGroup.gameObject:AddChild(self.ImgStar.gameObject)
        --         go.transform.localScale = self.ImgStar.localScale
        --         self.starNodes[i] = go
        --     end
        --     CfUtils.SetActive(go, checkInt(equipDojo.star) >= i)
        -- end
        self:RefreshStarGroup(checkInt(equipDojo.star))
    else
        CfUtils.SetActive(self.Content, false)
        CfUtils.SetActive(self.ImgIcon, true)
        CfUtils.SetActive(self.UIFX_CultivateOverseaEquipmentDialogBall, false)
        CfUtils.SetActive(self.Effect, false)
        CfUtils.SetUISwitchImage(self.Imgball1, 1)
        CfUtils.SetUISwitchParticleSystem(self.ParticleGlow, 1)
        CfUtils.SetUISwitchParticleSystem(self.ParticleLiuDong, 1)
        CfUtils.SetUISwitchParticleSystem(self.ParticleRing, 1)
        CfUtils.SetUISwitchParticleSystem(self.ParticleStar, 1)
    end
end

function CardProgressionCardEquipBtnNode:RefreshStarGroup(star)
    ---@type StarGroup
    local env = CfUtils.GetLuaScr(self.StarGroup, "Game.Behaviours.StarGroup")
    if isNull(env) then
        return
    end
    --- 装备解锁红装的只是改变品质 这里要减一
    local realStar = star >= (EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.StartStar)) and (star - 1) or star
    env:RefreshUI(realStar, 5, true)
end

---播放切换装备动画
function CardProgressionCardEquipBtnNode:PlaySwitchAnimation()
    local animation = self.AnimRoot.transform:GetComponent(typeof(CS.UnityEngine.Animation))
    if not animation then
        return
    end
    animation:Stop()
    animation:Play('CultivateOverseaEquipmentDialogBall_Switch')
end

---设置effect状态
function CardProgressionCardEquipBtnNode:SetEffectState(active)
    CfUtils.SetActive(self.Effect, active)
end

---刷新选中状态
---@param isSelected boolean 是否选中
function CardProgressionCardEquipBtnNode:RefreshSelectState(isSelected)
    CfUtils.SetActive(self.StatusSelect, isSelected == true)
end
